sys_variable_value.value:
(function execute(inputs, outputs) {
if(!inputs.message){
    outputs.finalvalue = parseFloat(inputs.proportionalvalues[inputs.targetcurrency]) * inputs.initialvalue;
}
else {
    outputs.finalvalue = 0;
}
})(inputs, outputs);

